import concurrent.futures,datetime,hashlib,json,os,platform,subprocess,time
from pathlib import Path
ROOT=Path.cwd();WORK=ROOT/'.work/measure-20261120'
old=json.loads((ROOT/'docs/measurements/2026-11-17-size-speed.json').read_text(encoding='utf-8'))
variants={'full':[],'no-float':['float'],'no-graphics':['graphics'],'no-audio':['audio'],'no-graphics-float':['graphics','float'],'no-debug':['debug'],'no-extension':['extension'],'minimal':['float','files','help','tools','image','graphics','audio','debug','extension']}
prior={c['variant']:c['feature_checks'] for c in old['build_and_size']['configurations'] if c['target']=='x86_64-windows-gnu'}
def execute(target,binary,code):
 args=[str(binary),'-e',code] if 'windows' in target else ['wsl.exe','--exec',str(binary).replace('D:\\','/mnt/d/').replace('\\','/'),'-e',code]
 r=subprocess.run(args,cwd=ROOT,capture_output=True,text=True,encoding='utf-8',timeout=30)
 return {'source':code,'stdout':r.stdout,'stderr':r.stderr,'exit_code':r.returncode}
def build(job):
 target,variant,disabled,baseline=job;label=target+'-'+variant+('-baseline' if baseline else '');prefix=WORK/label
 cwd=WORK/'baseline-src' if baseline else ROOT
 cmd=['zig','build','-Dtarget='+target,'-Doptimize=fast','-Dcpu=baseline','-Dstrip=true']+['-D'+v+'=false' for v in disabled]+['--prefix',str(prefix)]
 start=time.monotonic()
 with (WORK/(label+'.log')).open('w',encoding='utf-8') as log:r=subprocess.run(cmd,cwd=cwd,stdout=log,stderr=subprocess.STDOUT)
 assert r.returncode==0,(label,(WORK/(label+'.log')).read_text(encoding='utf-8')[-6000:])
 binary=prefix/'bin'/('sigma.exe' if 'windows' in target else 'sigma')
 smoke=execute(target,binary,'40 2 + . BYE');assert smoke['exit_code']==0 and smoke['stdout'].strip()=='42' and not smoke['stderr'],(label,smoke)
 checks=[]
 if not baseline:
  for check in prior.get(variant,[]):
   actual=execute(target,binary,check['source']);actual['expected']=check['expected'];actual['passed']=actual['exit_code']==0 and actual['stdout'].strip()==actual['expected'] and not actual['stderr'];assert actual['passed'],(label,actual);checks.append(actual)
  if 'extension' not in disabled:
   actual=execute(target,binary,'REQUIRE-EXTENSION ALSO EXTENSION [DEFINED] EXEC-LIMITED . BYE');actual['expected']='0' if 'debug' in disabled else '-1';assert actual['exit_code']==0 and actual['stdout'].strip()==actual['expected'] and not actual['stderr'],(label,actual);checks.append(actual)
  actual=execute(target,binary,'[DEFINED] F+ . [DEFINED] OPEN-FILE . BYE');actual['expected']=('0' if 'float' in disabled else '-1')+' '+('0' if 'files' in disabled else '-1');assert actual['exit_code']==0 and actual['stdout'].strip()==actual['expected'] and not actual['stderr'],(label,actual);checks.append(actual)
 result={'label':label,'target':target,'variant':variant,'disabled':disabled,'source_commit':'8f4a968' if baseline else subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'command':cmd,'build_cwd':str(cwd.relative_to(ROOT)) if baseline else '.', 'executable':str(binary.relative_to(ROOT)).replace('\\','/'),'bytes':binary.stat().st_size,'sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'smoke':smoke,'feature_checks':checks,'build_seconds':round(time.monotonic()-start,3)}
 (WORK/(label+'.json')).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(label,result['bytes'],'bytes',flush=True);return result
jobs=[(target,name,disabled,False) for target in ['x86_64-windows-gnu','x86_64-linux-musl'] for name,disabled in variants.items()]+[(target,'full',[],True) for target in ['x86_64-windows-gnu','x86_64-linux-musl']]
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:rows=list(pool.map(build,jobs))
report={'measured_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'host':platform.platform(),'zig':subprocess.check_output(['zig','version'],text=True).strip(),'optimize':'fast','cpu':'baseline','strip':True,'configurations':rows,'minimal_definition':'nine groups disabled, includes extension; previous report disabled eight groups and retained extension'}
(WORK/'build-size.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

