root=Path.cwd();work=root/'.work/measure-20261120'
size=json.loads((work/'build-size.json').read_text(encoding='utf-8'))
linux=json.loads((work/'benchmark-linux.json').read_text(encoding='utf-8'))
windows=json.loads((work/'benchmark-windows.json').read_text(encoding='utf-8'))
env=json.loads((work/'environment.json').read_text(encoding='utf-8'));env['linux']=json.loads((work/'linux-environment.json').read_text(encoding='utf-8'));env['cpu_model']='AMD Ryzen 7 7700 8-Core Processor';env['logical_processors']=16
names={'arithmetic':'整数演算','stacks':'スタック操作','calls':'入れ子呼出し','variables':'定数・変数','loops':'LOOP','plus-loop':'+LOOP','extended':'シフト・ビット演算','float':'浮動小数点'}
variant_names={'full':'通常','no-float':'浮動小数点なし','no-graphics':'グラフィックスだけなし','no-audio':'サウンドだけなし','no-graphics-float':'グラフィックス・浮動小数点なし','no-debug':'debug機能なし','no-extension':'EXTENSIONなし','minimal':'最小（9群なし）'}
def gm(values):return math.exp(statistics.mean(map(math.log,values)))
def summary(bench):
 rows=bench['cases'];ratios={label:[row['engines']['current']['median_us']/row['engines'][label]['median_us'] for row in rows.values()] for label in rows['arithmetic']['engines'] if label!='current'}
 return {'ratios':{label:{'geometric_mean':gm(v),'minimum':min(v),'maximum':max(v)} for label,v in ratios.items()},'change_percent_geometric_mean':100*(gm(ratios['before'])-1),'current_max_spread_percent':max(100*(row['engines']['current']['max_us']/row['engines']['current']['min_us']-1) for row in rows.values())}
ls,ws=summary(linux),summary(windows)
windows_initial=json.loads((work/'benchmark-windows-initial.json').read_text(encoding='utf-8'));wi=summary(windows_initial)
for bench,target in [(linux,'x86_64-linux-musl'),(windows,'x86_64-windows-gnu')]:
 for label,suffix in [('current','-full'),('before','-full-baseline')]:
  metadata=next(e for e in bench['engines'] if e['label']==label);expected=next(c for c in size['configurations'] if c['target']==target and c['label'].endswith(suffix));assert metadata['sha256']==expected['sha256']
report={'measured_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_commit':env['git'],'version':(root/'VERSION').read_text().strip(),'baseline_commit': __import__('subprocess').check_output(['git','rev-parse','8f4a968'],text=True).strip(),'application_sources_changed':False,'environment':env,'harness_tests':{'windows':'3 tests OK','linux':'3 tests OK'},'build_and_size':size,'benchmark_linux':linux,'benchmark_windows':windows,'benchmark_windows_initial':windows_initial,'windows_repeat_reason':'Initial current plus-loop samples had a max/min ratio of 2.625; reran all eight cases with identical CPU affinity and protocol, retaining all initial samples.','summary':{'linux':ls,'windows':ws,'windows_initial':wi},'benchmark_commands':json.loads((work/'benchmark-commands.json').read_text(encoding='utf-8')),'sources':{name:(work/name).read_text(encoding='utf-8-sig') for name in ['build-size.py','check-features.py','run-benchmarks.py','collect-report.py','repeat-windows.py']}}
out=root/'docs/measurements/2026-11-20-size-speed.json';out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lines=['# サイズ測定・速度比較（2026-11-20）','','対象はコミット`789420e`。変更前の`8f4a968`も同じZigで別の作業領域にビルドし直した。今回の測定作業ではアプリケーションのコードを変更していない。署名・インストーラー・配布パッケージの作成は行っていない。','','## 結果','']
for target,label in [('x86_64-windows-gnu','Windows'),('x86_64-linux-musl','Linux')]:
 current=next(c for c in size['configurations'] if c['target']==target and c['label'].endswith('-full'));before=next(c for c in size['configurations'] if c['target']==target and c['label'].endswith('-baseline'));lines.append(f"- {label}通常版：**{current['bytes']:,}バイト（{current['bytes']/1048576:.3f} MiB）**。変更前比+{current['bytes']-before['bytes']:,}バイト（+{100*(current['bytes']/before['bytes']-1):.2f}%）。")
lines += [f"- 8カーネルの所要時間は、変更前比の幾何平均でLinux **{ls['change_percent_geometric_mean']:.1f}%**、Windows（参考値） **{ws['change_percent_geometric_mean']:.1f}%**。負数は時間短縮。",f"- LinuxでのGforth通常版比は**{ls['ratios']['gforth-1.0.2']['geometric_mean']:.2f}倍**、fast版比は**{ls['ratios']['gforth-fast-1.0.2']['geometric_mean']:.2f}倍**の所要時間。今回もGforthの方が速かった。",'', 'これは小さな診断カーネルの結果であり、実用アプリケーション全般の速度ではない。変更前後の差はコミット全体の比較で、grapheme・ファイルシステム・実行制御の各変更や生成命令ごとの寄与を分離したものではない。','','## 条件と確認','','- AMD Ryzen 7 7700、8コア/16論理CPU、Windows 11。Zig **0.17.1**。両OSとも`-Doptimize=fast -Dcpu=baseline -Dstrip=true`。Linuxはx86_64-linux-muslへのクロスビルド。', '- 出力先は`.work/measure-20261120/`。現行16構成と比較用通常版2構成、計18実行体で`40 2 + . BYE`の42と正常終了を確認。機能除外など48照合も成功。', '- 最小構成はfloat/files/help/tools/image/graphics/audio/debug/extensionの9群をすべて無効化。2026-11-17の最小構成は8群無効でEXTENSIONを残しており、同じ構成として比較しない。', '- サイズは実行ファイル単体。ライセンス文書、依存ライブラリー、インストール容量、実行時メモリーを含まない。', '- 速度は通常版でCPU親和性0。各カーネル1億反復、各エンジン1回warmupを除外し、その後7回。ラウンドごとにエンジン順を反転。ビルド・テストと速度測定を同時実行せず、LinuxとWindowsも順番に測定。', '- 既存schema version 2の測定器を変更せず使用。READY/DONEの入力ハンドシェイク間の子プロセスCPU時間を測定し、起動・ソース読込み・コンパイル・終了を除く。境界の入出力は含む。測定器テストはWindows/Linuxとも3件成功。', '- 整数チェックサムは各OSの全エンジン・全試行で一致。`--max-steps`やEXEC-LIMITEDは使っていない。652のCLI計数・入口付き処理の測定とは条件が異なる（[別記録](EXECUTION_CONTROL_IMPLEMENTATION.md)）。', '- WSL Linux 6.18.33.2、glibc 2.43、Python 3.14.4。既存Gforth 1.0.2 amd64通常/fastエンジンを使用。同じコンパイラー/フラグで再ビルドした比較ではない。実行体のSHA-256を記録。','','## 実行ファイルのサイズ','','| 対象 | 構成 | バイト | MiB | 通常版からの削減 |','| --- | --- | ---: | ---: | ---: |']
for target,label in [('x86_64-windows-gnu','Windows'),('x86_64-linux-musl','Linux')]:
 full=next(c['bytes'] for c in size['configurations'] if c['target']==target and c['label'].endswith('-full'))
 for c in size['configurations']:
  if c['target']==target and not c['label'].endswith('-baseline'):lines.append(f"| {label} | {variant_names[c['variant']]} | {c['bytes']:,} | {c['bytes']/1048576:.3f} | {100*(1-c['bytes']/full):.1f}% |")
lines += ['','## Linux CPU時間','','| カーネル | 現行 ms | 変更前 ms | 変化 | Gforth通常 ms | Gforth-fast ms | 現行/通常 | 現行/fast |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
for name,c in linux['cases'].items():
 e=c['engines'];n=e['current']['median_us'];b=e['before']['median_us'];g=e['gforth-1.0.2']['median_us'];f=e['gforth-fast-1.0.2']['median_us'];lines.append(f'| {names[name]} | {n/1000:.3f} | {b/1000:.3f} | {100*(n/b-1):+.1f}% | {g/1000:.3f} | {f/1000:.3f} | {n/g:.2f} | {n/f:.2f} |')
